() => {
  const svgs = Array.from(document.querySelectorAll('svg'));
  return svgs.map((svg, index) => {
    const parentText = svg.parentElement ? svg.parentElement.innerText.slice(0, 80) : '';
    const siblingText = svg.nextElementSibling ? svg.nextElementSibling.textContent : '';
    const grand = svg.closest('button');
    const cardText = grand ? grand.innerText.slice(0, 120) : '';
    return {
      index,
      width: svg.getAttribute('width'),
      height: svg.getAttribute('height'),
      viewBox: svg.getAttribute('viewBox'),
      className: svg.getAttribute('class'),
      parentText,
      siblingText,
      cardText,
      outerHTML: svg.outerHTML,
    };
  });
}

() => {
  const svg = document.querySelector('.lucide-map-pin');
  if (!svg) return null;
  const style = getComputedStyle(svg);
  const parent = svg.parentElement;
  const parentStyle = parent ? getComputedStyle(parent) : null;
  const text = parent ? parent.querySelector('span, p') : null;
  const textStyle = text ? getComputedStyle(text) : null;
  const rect = svg.getBoundingClientRect();
  const textRect = text ? text.getBoundingClientRect() : null;
  return {
    className: svg.getAttribute('class'),
    width: style.width,
    height: style.height,
    color: style.color,
    stroke: style.stroke,
    strokeWidth: svg.getAttribute('stroke-width'),
    rect: { width: rect.width, height: rect.height, top: rect.top, bottom: rect.bottom },
    parentDisplay: parentStyle && parentStyle.display,
    parentAlignItems: parentStyle && parentStyle.alignItems,
    parentGap: parentStyle && parentStyle.gap,
    textColor: textStyle && textStyle.color,
    textFontSize: textStyle && textStyle.fontSize,
    textLineHeight: textStyle && textStyle.lineHeight,
    textRect,
  };
}

