test('counts currently available online doctors instead of the isOnline flag', async () => {
  const firstPageDoctors = Array.from({ length: 10 }, (_value, index) => {
    const doctorIndex = index + 1;

    return {
      ...createMockDoctor(doctorIndex),
      isOnline: true,
      queueExpectedTime:
        doctorIndex === 3 || doctorIndex === 4
          ? '2024-05-09T12:07:54.8944168Z'
          : '2099-01-01T00:00:00.000Z',
    };
  });

  mockGetProviderOptions.mockResolvedValue({
    data: {
      region: ['Hong Kong'],
      specialty: ['General Practice'],
    },
  });
  mockFilterBySpecialty.mockResolvedValue({
    success: true,
    data: firstPageDoctors,
  });

  const screen = render(
    <ThemeContext.Provider value={mockTheme}>
      <AppointmentsScreen />
    </ThemeContext.Provider>
  );

  await waitFor(() => {
    expect(screen.getByTestId('appointments-doctor-list')).toBeTruthy();
  });

  await act(async () => {
    await screen.getByTestId('appointments-doctor-list').props.fetchData({
      pageIndex: 1,
      pageSize: 10,
      prevItems: [],
    });
  });

  expect(screen.getByText('8 doctors')).toBeTruthy();

  let cardRenderer: TestRenderer.ReactTestRenderer;

  act(() => {
    cardRenderer = TestRenderer.create(
      screen.getByTestId('appointments-doctor-list').props.renderItem({
        item: firstPageDoctors[2],
        index: 2,
        selected: false,
      })
    );
  });

  expect(
    cardRenderer!.root.findByProps({
      testID: 'appointments-doctor-online-status-provider-3',
    }).props.source
  ).toBe(assets.Offline());
  expect(
    cardRenderer!.root.findAllByProps({
      testID: 'appointments-doctor-queue-provider-3',
    })
  ).toHaveLength(0);

  act(() => {
    cardRenderer!.update(
      screen.getByTestId('appointments-doctor-list').props.renderItem({
        item: firstPageDoctors[0],
        index: 0,
        selected: false,
      })
    );
  });

  expect(
    cardRenderer!.root.findByProps({
      testID: 'appointments-doctor-online-status-provider-1',
    }).props.source
  ).toBe(assets.online());
});

