async () => {
  const src = Array.from(document.scripts).map(s => s.src).find(src => src.includes('/assets/index-'));
  if (!src) return {src:null};
  const text = await (await fetch(src)).text();
  const needles = ['Confirm Booking', 'Book with ', 'Patient Information', 'Describe your symptoms'];
  const snippets = {};
  for (const needle of needles) {
    const index = text.indexOf(needle);
    snippets[needle] = index >= 0 ? text.slice(Math.max(0,index-1500), Math.min(text.length,index+2500)) : null;
  }
  return {src, length:text.length, snippets};
}

